(async()=>{const adapter=await navigator.gpu.requestAdapter(),device=await adapter.requestDevice(),out=[];
 const code=`@vertex fn vertex(@builtin(vertex_index) index:u32)->@builtin(position) vec4f{let points=array<vec2f,3>(vec2f(-.75,-.5),vec2f(.75,-.5),vec2f(0,.75));return vec4f(points[index],0,1);}@fragment fn fragment()->@location(0) vec4f{return vec4f(.25,.5,.75,1);}`;
 const module=device.createShaderModule({code});const pipeline=device.createRenderPipeline({layout:'auto',vertex:{module,entryPoint:'vertex'},fragment:{module,entryPoint:'fragment',targets:[{format:'rgba8unorm'}]}});
 const texture=device.createTexture({size:[8,8],format:'rgba8unorm',usage:GPUTextureUsage.RENDER_ATTACHMENT|GPUTextureUsage.COPY_SRC});
 async function run(loadOp,draw,scissor,storeOp='store'){const buffer=device.createBuffer({size:256*8,usage:GPUBufferUsage.COPY_DST|GPUBufferUsage.MAP_READ});const encoder=device.createCommandEncoder();const pass=encoder.beginRenderPass({colorAttachments:[{view:texture.createView(),loadOp,storeOp,clearValue:[0,0,0,1]}]});if(draw){pass.setPipeline(pipeline);if(scissor)pass.setScissorRect(...scissor);pass.draw(3);}pass.end();encoder.copyTextureToBuffer({texture},{buffer,bytesPerRow:256},[8,8]);device.queue.submit([encoder.finish()]);await buffer.mapAsync(GPUMapMode.READ);const a=new Uint8Array(buffer.getMappedRange());out.push(Array.from({length:8},(_,y)=>Array.from(a.slice(y*256,y*256+32))));buffer.unmap();buffer.destroy()}
 await run('clear',true);await run('load',true,[0,0,4,8]);await run('clear',false);await run('load',true,undefined,'discard');
 device.pushErrorScope('validation');const foreign=await (await navigator.gpu.requestAdapter()).requestDevice();const encoder=device.createCommandEncoder();encoder.copyTextureToBuffer({texture},{buffer:foreign.createBuffer({size:2048,usage:GPUBufferUsage.COPY_DST}),bytesPerRow:256},[8,8]);device.queue.submit([encoder.finish()]);out.push((await device.popErrorScope())?.constructor.name);
 const write=device.createTexture({size:[4,3],format:'bgra8unorm',usage:3}),copy=device.createTexture({size:[4,3],format:'bgra8unorm',usage:3});device.queue.writeTexture({texture:write,origin:[1,1]},new Uint8Array([11,22,33,255,44,55,66,255]),{bytesPerRow:8},[2,1]);
 const b=device.createBuffer({size:768,usage:9}),e=device.createCommandEncoder();e.copyTextureToTexture({texture:write},{texture:copy},[4,3]);e.copyTextureToBuffer({texture:copy},{buffer:b,bytesPerRow:256},[4,3]);device.queue.submit([e.finish()]);await b.mapAsync(1);const bytes=new Uint8Array(b.getMappedRange());out.push(Array.from({length:3},(_,y)=>Array.from(bytes.slice(y*256,y*256+16))));b.unmap();
 const canvas=document.createElement('canvas');canvas.width=4;canvas.height=3;const context=canvas.getContext('webgpu');context.configure({device,format:'rgba8unorm',alphaMode:'opaque'});const current=context.getCurrentTexture();out.push(current===context.getCurrentTexture());const ce=device.createCommandEncoder(),pass=ce.beginRenderPass({colorAttachments:[{view:current.createView(),loadOp:'clear',storeOp:'store',clearValue:[.2,.4,.6,.5]}]});pass.end();device.queue.submit([ce.finish()]);const target=document.createElement('canvas');target.width=4;target.height=3;const ctx=target.getContext('2d');ctx.drawImage(canvas,0,0);out.push(Array.from(ctx.getImageData(0,0,1,1).data));canvas.width=5;out.push(context.getCurrentTexture()===current);context.unconfigure();out.push(context.getConfiguration());
 device.pushErrorScope('validation');const open=device.createCommandEncoder();open.beginRenderPass({colorAttachments:[{view:texture.createView(),loadOp:'load',storeOp:'store'}]});open.finish();out.push((await device.popErrorScope())?.constructor.name);
 texture.destroy();device.destroy();foreign.destroy();return out})()